package com.bank.df.engine;

import com.bank.df.model.Row;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.logging.Logger;

// Simulates the Spark DataFrame model: lazy transformations, execution on an action.
public class MiniDataFrame {
    private static final Logger log = Logger.getLogger(MiniDataFrame.class.getName());

    private final List<Row> source;
    // The logical plan: a chain of lazy operations (nothing runs until an action).
    private final List<Consumer<List<Row>>> plan = new ArrayList<>();

    public MiniDataFrame(List<Row> source) { this.source = source; }

    // Transformation — lazy: records a filter-equivalent into the plan.
    public MiniDataFrame filter(Predicate<Row> keep) {
        plan.add(rows -> rows.removeIf(r -> !keep.test(r)));
        log.info("plan += filter (LAZY, not executed)");
        return this;
    }

    // Transformation — fillna on amount.
    public MiniDataFrame fillNaAmount(BigDecimal fill) {
        plan.add(rows -> rows.forEach(r -> { if (r.getAmount() == null) r.setAmount(fill); }));
        log.info("plan += fillNaAmount (LAZY)");
        return this;
    }

    // Transformation — when/otherwise to set a status column.
    public MiniDataFrame withColumnStatus(BigDecimal threshold) {
        plan.add(rows -> rows.forEach(r ->
            r.setStatus(r.getAmount().compareTo(threshold) > 0 ? "HIGH_VALUE" : "NORMAL")));
        log.info("plan += withColumn(status) via when/otherwise (LAZY)");
        return this;
    }

    // ACTION — collect triggers the whole plan now.
    public List<Row> collect() {
        log.info("ACTION collect(): optimizing + executing the plan");
        List<Row> rows = new ArrayList<>();
        for (Row r : source) rows.add(new Row(r.getAccountId(), r.getAmount())); // copy (immutability)
        for (Consumer<List<Row>> step : plan) step.accept(rows);
        return rows;
    }

    // ACTION — count also triggers execution.
    public long count() {
        log.info("ACTION count(): executing the plan");
        return collect().size();
    }
}
