package com.bank.df;

import com.bank.df.engine.MiniDataFrame;
import com.bank.df.model.Row;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class DataFrameDemo {
    private static final Logger log = Logger.getLogger(DataFrameDemo.class.getName());

    public static void main(String[] args) {
        List<Row> data = new ArrayList<>(List.of(
            new Row("SAV2001", new BigDecimal("1200")),
            new Row("CUR3001", new BigDecimal("150000")),
            new Row("SAV2001", null),                     // null amount
            new Row("CUR3001", new BigDecimal("-50"))     // will be filtered after fill? no: filter first
        ));

        log.info("=== Build lazy plan (no execution yet) ===");
        MiniDataFrame df = new MiniDataFrame(data)
            .fillNaAmount(BigDecimal.ZERO)                // fillna
            .filter(r -> r.getAmount().compareTo(BigDecimal.ZERO) >= 0) // dropna-like / filter
            .withColumnStatus(new BigDecimal("100000"));  // when/otherwise

        log.info("Plan built. Still nothing executed.");

        log.info("=== Trigger with an ACTION ===");
        List<Row> result = df.collect();
        result.forEach(r -> log.info(r.getAccountId() + " amount=" + r.getAmount() + " status=" + r.getStatus()));
        log.info("count() = " + df.count());
    }
}
